using System.Collections;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Runtime.Versioning;
using System.Xml.XPath;
using Xsl3.Runtime;

namespace Xsl3
{
    /// <summary>
    /// This is the executable command generated by the XmlILGenerator.
    /// </summary>
    internal sealed class XmlILCommand
    {
        private readonly ExecuteDelegate _delExec;
        private readonly XmlQueryStaticData _staticData;

        /// <summary>
        /// Constructor.
        /// </summary>
        public XmlILCommand(ExecuteDelegate delExec, XmlQueryStaticData staticData)
        {
            Debug.Assert(delExec != null && staticData != null);
            _delExec = delExec;
            _staticData = staticData;
        }

        /// <summary>
        /// Return query static data required by the runtime.
        /// </summary>
        public XmlQueryStaticData StaticData
        {
            get { return _staticData; }
        }


        /// <summary>
        /// Execute the dynamic assembly generated by the XmlILGenerator.
        /// </summary>
        public void Execute(object defaultDocument, XmlResolver? dataSources, XsltArgumentList? argumentList, XmlWriter writer)
        {
            try
            {
                // Xsl3: upstream unwraps System.Private.Xml's XmlAsyncCheckWriter and XmlWellFormedWriter here to
                // reach the stock raw writer. Those are internal to System.Private.Xml, so writers that callers
                // create always take the wrapper path below. XslCompiledTransform's Stream, TextWriter and URI
                // overloads instead pass Xsl3's own raw writer chain (XmlWriterSettingsInternals.CreateRawWriter),
                // which is what upstream would have extracted, since XSLT output settings use ConformanceLevel.Auto.
                if (_staticData.Xslt2 && writer is not XmlRawWriter)
                {
                    // Xsl3: the principal result of a 2.0+ stylesheet goes through a PrincipalResult, which applies
                    // xhtml, character maps and normalization and serves xsl:result-document without href.
                    PrincipalResult principal = writer as PrincipalResult ?? new PrincipalResult(writer, _staticData.OutputExtras);
                    PrincipalResult? saved = XmlQueryRuntime.Principal;
                    XmlQueryRuntime.Principal = principal;
                    try
                    {
                        Execute(defaultDocument, dataSources, argumentList, new XmlMergeSequenceWriter(new XmlRawWriterWrapper(principal)));
                    }
                    finally
                    {
                        XmlQueryRuntime.Principal = saved;
                    }
                }
                else if (writer is XmlRawWriter rawWriter)
                {
                    Execute(defaultDocument, dataSources, argumentList, new XmlMergeSequenceWriter(rawWriter));
                }
                else
                {
                    // Wrap Writer in RawWriter
                    Execute(defaultDocument, dataSources, argumentList, new XmlMergeSequenceWriter(new XmlRawWriterWrapper(writer)));
                }
            }
            finally
            {
                writer.Flush();
            }
        }

        /// <summary>
        /// Execute the dynamic assembly generated by the XmlILGenerator.
        /// </summary>
        /// <summary>
        /// Xsl3: runs the query and returns its result as a sequence instead of serializing it ("raw" result
        /// delivery, used by the XPath 3.1 API). Nodes keep their identity; atomic values come back as items.
        /// </summary>
        public IList<XPathItem> Evaluate(object defaultDocument, XmlResolver? dataSources, XsltArgumentList? argumentList)
        {
            var results = new XmlCachedSequenceWriter();
            Execute(defaultDocument, dataSources, argumentList, results);
            return results.ResultSequence;
        }

        private void Execute(object defaultDocument, XmlResolver? dataSources, XsltArgumentList? argumentList, XmlSequenceWriter results)
        {
            Debug.Assert(results != null);

            // Ensure that dataSources is always non-null
            dataSources ??= XmlResolver.ThrowingResolver;

            try
            {
                _delExec(new XmlQueryRuntime(_staticData, defaultDocument, dataSources, argumentList, results));
            }
            catch (System.InsufficientExecutionStackException e)
            {
                // Xsl3: raised by the guard at template and function entry (SPEC §21.2).
                throw new XslTransformException(e, "Q{http://xsl3/err}recursion-limit: the transformation recursed too deeply for the available stack");
            }
            catch (System.OperationCanceledException e)
            {
                throw new XslTransformException(e, "Q{http://xsl3/err}cancelled: the transformation was cancelled");
            }
        }
    }
}
